import { expect } from "chai"
import type { McpHub } from "@/services/mcp/McpHub"
import { ModelFamily } from "@/shared/prompts"
import { Logger } from "@/shared/services/Logger"
import { PromptBuilder } from "../registry/PromptBuilder"
import { SystemPromptSection } from "../templates/placeholders"
import type { ComponentRegistry, PromptVariant, SystemPromptContext } from "../types"
import { createVariant } from "../variants/variant-builder"
import { mockProviderInfo } from "./integration.test"

describe("PromptBuilder", () => {
	const mockContext: SystemPromptContext = {
		cwd: "/test/project",
		ide: "TestIde",
		supportsBrowserUse: true,
		mcpHub: {
			getServers: () => [],
			getMcpServersPath: () => "/test/mcp-servers",
			getSettingsDirectoryPath: () => "/test/settings",
			clientVersion: "1.0.0",
			disposables: [],
		} as unknown as McpHub,
		focusChainSettings: {
			enabled: true,
			remindClineInterval: 6,
		},
		browserSettings: {
			viewport: {
				width: 1280,
				height: 720,
			},
		},
		isTesting: true,
		providerInfo: mockProviderInfo,
		yoloModeToggled: false,
	}

	const mockComponents: ComponentRegistry = {
		SYSTEM_INFO_SECTION: async () => "SYSTEM INFORMATION\n\nOS: macOS\nShell: zsh",
		TOOL_USE_SECTION: async () => "TOOL USE\n\n- {{TOOLS}}",
		CAPABILITIES_SECTION: async () => "CAPABILITIES\n\n- Code execution\n- File operations",
		RULES_SECTION: async () => "RULES\n\n- Follow best practices\n- Be concise",
	}

	const baseVariant: PromptVariant = {
		id: "test-model",
		family: ModelFamily.GENERIC,
		matcher: () => true,
		version: 1,
		description: "A test model",
		tags: ["test"],
		labels: { test: 1 },
		config: {
			modelName: "test-model",
			temperature: 0.7,
		},
		baseTemplate:
			"You are Cline.\n\n{{TOOL_USE_SECTION}}\n\n{{CAPABILITIES_SECTION}}\n\n{{RULES_SECTION}}\n\n{{SYSTEM_INFO_SECTION}}",
		componentOrder: [
			SystemPromptSection.TOOL_USE,
			SystemPromptSection.CAPABILITIES,
			SystemPromptSection.RULES,
			SystemPromptSection.SYSTEM_INFO,
		],
		componentOverrides: {},
		placeholders: {
			MODEL_FAMILY: "test",
		},
	}

	describe("build", () => {
		it("should build a complete prompt", async () => {
			const builder = new PromptBuilder(baseVariant, mockContext, mockComponents)
			const result = await builder.build()

			expect(result).to.include("You are Cline.")
			expect(result).to.include("TOOL USE")
			expect(result).to.include("CAPABILITIES")
			expect(result).to.include("RULES")
			expect(result).to.include("SYSTEM INFORMATION")
			expect(result).to.include("OS: macOS")
		})

		it("should handle missing components gracefully", async () => {
			const incompleteComponents: ComponentRegistry = {
				TOOL_USE_SECTION: async () => "TOOL USE REPLACER",
				SYSTEM_INFO_SECTION: async () => "SYSTEM INFO",
			}

			// Mock Logger.warn to capture and verify warnings
			const originalWarn = Logger.warn
			const warnSpy = {
				calls: [] as any[],
				warn: (...args: any[]) => {
					warnSpy.calls.push(args)
				},
			}
			Logger.warn = warnSpy.warn

			try {
				const builder = new PromptBuilder(baseVariant, mockContext, incompleteComponents)
				const result = await builder.build()

				expect(result).to.include("You are Cline.")
				expect(result).to.include("TOOL USE REPLACER")
				expect(result).to.include("SYSTEM INFO")
				// Missing components should not break the build

				// Verify that warnings were logged for missing components
				expect(warnSpy.calls).to.have.length(2)
				expect(warnSpy.calls[0][0]).to.include("Warning: Component 'CAPABILITIES_SECTION' not found")
				expect(warnSpy.calls[1][0]).to.include("Warning: Component 'RULES_SECTION' not found")
			} finally {
				// Restore original Logger.warn
				Logger.warn = originalWarn
			}
		})

		it("should apply component overrides", async () => {
			const variantWithOverrides: PromptVariant = {
				...baseVariant,
				componentOverrides: {
					SYSTEM_INFO_SECTION: {
						template: "CUSTOM SYSTEM INFO: {{os}} on {{shell}}",
					},
				},
			}

			const customComponents: ComponentRegistry = {
				...mockComponents,
				SYSTEM_INFO_SECTION: async (variant) => {
					let template = variant.componentOverrides?.SYSTEM_INFO_SECTION?.template || "DEFAULT"

					if (typeof template === "function") {
						const mockContext = { cwd: "/test", yoloModeToggled: false } as SystemPromptContext
						template = template(mockContext)
					}
					return template.replace("{{os}}", "Linux").replace("{{shell}}", "bash")
				},
			}

			const builder = new PromptBuilder(variantWithOverrides, mockContext, customComponents)
			const result = await builder.build()

			expect(result).to.include("CUSTOM SYSTEM INFO: Linux on bash")
		})

		it("should resolve runtime placeholders", async () => {
			const contextWithRuntime = {
				...mockContext,
				runtimePlaceholders: {
					USER_NAME: "TestUser",
					PROJECT_TYPE: "React",
				},
			}

			const templateWithRuntime: PromptVariant = {
				...baseVariant,
				baseTemplate: "Hello {{USER_NAME}}! Working on {{PROJECT_TYPE}} project.\n\n{{TOOLS}}",
			}

			const builder = new PromptBuilder(templateWithRuntime, contextWithRuntime as SystemPromptContext, mockComponents)
			const result = await builder.build()

			expect(result).to.include("Hello TestUser!")
			expect(result).to.include("Working on React project.")
		})

		it("should handle component errors gracefully", async () => {
			// Mock Logger.warn to suppress warning output and verify it's called
			const originalWarn = Logger.warn
			const warnSpy = {
				calls: [] as any[],
				warn: (...args: any[]) => {
					warnSpy.calls.push(args)
				},
			}
			Logger.warn = warnSpy.warn

			try {
				const failingComponents: ComponentRegistry = {
					TOOL_USE_SECTION: async () => "TOOL USE CONTENT",
					SYSTEM_INFO_SECTION: async () => {
						throw new Error("Component failed")
					},
					CAPABILITIES_SECTION: async () => "CAPABILITIES WORK",
					RULES_SECTION: async () => "RULES WORK",
				}

				const builder = new PromptBuilder(baseVariant, mockContext, failingComponents)
				const result = await builder.build()

				// Should still build successfully despite failing component
				expect(result).to.include("You are Cline.")
				expect(result).to.include("CAPABILITIES WORK")
				expect(result).to.include("TOOL USE CONTENT")

				// Verify that the warning was logged for the failing component
				expect(warnSpy.calls).to.have.length(1)
				expect(warnSpy.calls[0][0]).to.include("Failed to build component 'SYSTEM_INFO_SECTION'")
			} finally {
				// Restore original Logger.warn
				Logger.warn = originalWarn
			}
		})
	})

	describe("getBuildMetadata", () => {
		it("should return build metadata", () => {
			const builder = new PromptBuilder(baseVariant, mockContext, mockComponents)
			const metadata = builder.getBuildMetadata()

			expect(metadata.variantId).to.equal("test-model")
			expect(metadata.version).to.equal(1)
			expect(metadata.componentsUsed).to.deep.equal([
				"TOOL_USE_SECTION",
				"CAPABILITIES_SECTION",
				"RULES_SECTION",
				"SYSTEM_INFO_SECTION",
			])
			expect(metadata.placeholdersResolved).to.include("TOOL_USE_SECTION")
			expect(metadata.placeholdersResolved).to.include("CAPABILITIES_SECTION")
		})
	})

	describe("postProcess", () => {
		it("should clean up multiple empty lines", async () => {
			const templateWithExtraLines: PromptVariant = {
				...baseVariant,
				baseTemplate: "Line 1\n\n\n\nLine 2\n\n\n{{TOOLS}}",
			}

			const builder = new PromptBuilder(templateWithExtraLines, mockContext, mockComponents)
			const result = await builder.build()

			// Should not have more than 2 consecutive newlines
			expect(result).to.not.match(/\n\s*\n\s*\n/)
		})

		it("should ensure proper section separation", async () => {
			const templateWithSections: PromptVariant = {
				...baseVariant,
				baseTemplate: "Section 1\n====\nSection 2\n====\n{{TOOLS}}",
			}

			const builder = new PromptBuilder(templateWithSections, mockContext, mockComponents)
			const result = await builder.build()

			expect(result).to.include("====\n\nSection 2")
		})
	})

	describe("VariantBuilder auto-generation", () => {
		it("should auto-generate baseTemplate from componentOrder when not provided", () => {
			const config = createVariant(ModelFamily.GENERIC)
				.description("Test variant without explicit template")
				.version(1)
				.components(
					SystemPromptSection.AGENT_ROLE,
					SystemPromptSection.TOOL_USE,
					SystemPromptSection.CAPABILITIES,
					SystemPromptSection.RULES,
				)
				.matcher(() => true)
				.build()

			// Should have auto-generated a baseTemplate
			expect(config.baseTemplate).to.exist
			expect(config.baseTemplate).to.include("{{AGENT_ROLE_SECTION}}")
			expect(config.baseTemplate).to.include("{{TOOL_USE_SECTION}}")
			expect(config.baseTemplate).to.include("{{CAPABILITIES_SECTION}}")
			expect(config.baseTemplate).to.include("{{RULES_SECTION}}")

			// Should have separators between components
			expect(config.baseTemplate).to.include("====")

			// Should match the expected format
			const expectedTemplate = `{{${SystemPromptSection.AGENT_ROLE}}}

====

{{${SystemPromptSection.TOOL_USE}}}

====

{{${SystemPromptSection.CAPABILITIES}}}

====

{{${SystemPromptSection.RULES}}}`
			expect(config.baseTemplate).to.equal(expectedTemplate)
		})

		it("should use explicit baseTemplate when provided", () => {
			const customTemplate = "Custom template with {{AGENT_ROLE_SECTION}}"

			const config = createVariant(ModelFamily.GENERIC)
				.description("Test variant with explicit template")
				.version(1)
				.template(customTemplate)
				.matcher(() => true)
				.components(SystemPromptSection.AGENT_ROLE, SystemPromptSection.TOOL_USE)
				.build()

			// Should use the explicitly provided template
			expect(config.baseTemplate).to.equal(customTemplate)
		})

		it("should throw error when componentOrder is empty", () => {
			expect(() => {
				createVariant(ModelFamily.GENERIC)
					.description("Test variant with empty components")
					.version(1)
					.matcher(() => true)
					.components() // Empty components
					.build()
			}).to.throw("Component order is required")
		})
	})
})

import { expect } from "chai"
import type { McpHub } from "@/services/mcp/McpHub"
import { ModelFamily } from "@/shared/prompts"
import { PromptRegistry } from "../registry/PromptRegistry"
import type { SystemPromptContext } from "../types"
import { mockProviderInfo } from "./integration.test"

describe("PromptRegistry", () => {
	let registry: PromptRegistry
	const mockContext: SystemPromptContext = {
		cwd: "/test/project",
		ide: "TestIde",
		supportsBrowserUse: true,
		mcpHub: {
			getServers: () => [],
			getMcpServersPath: () => "/test/mcp-servers",
			getSettingsDirectoryPath: () => "/test/settings",
			clientVersion: "1.0.0",
			disposables: [],
		} as unknown as McpHub,
		focusChainSettings: {
			enabled: true,
			remindClineInterval: 6,
		},
		browserSettings: {
			viewport: {
				width: 1280,
				height: 720,
			},
		},
		isTesting: true,
		providerInfo: mockProviderInfo,
	}

	beforeEach(() => {
		// Get a fresh instance for each test
		PromptRegistry.dispose()
		registry = PromptRegistry.getInstance()
	})

	describe("getInstance", () => {
		it("should return singleton instance", () => {
			const instance1 = PromptRegistry.getInstance()
			const instance2 = PromptRegistry.getInstance()

			expect(instance1).to.equal(instance2)
		})
	})

	describe("getModelFamily", () => {
		it("should extract correct model families", async () => {
			const registry = PromptRegistry.getInstance()
			await registry.load()
			const testCases = [
				{ id: "claude-3-5-sonnet", expected: ModelFamily.GENERIC },
				{ id: "gpt-4-turbo", expected: ModelFamily.GENERIC },
				{ id: "gemini-pro", expected: ModelFamily.GENERIC },
				{ id: "qwen-max", provider: "lmstudio", expected: ModelFamily.XS },
				{ id: "anthropic/claude-3", expected: ModelFamily.GENERIC },
				{ id: "openai/gpt-4", expected: ModelFamily.GENERIC },
				{ id: "google/gemini", expected: ModelFamily.GENERIC },
				{ id: "claude-sonnet-4", expected: ModelFamily.NEXT_GEN },
				{ id: "gpt-5", provider: "cline", expected: ModelFamily.NATIVE_GPT_5, useNativeTools: true },
				{ id: "gpt-5", provider: "openai-native", expected: ModelFamily.NATIVE_GPT_5, useNativeTools: true },
				{ id: "gpt-oss-120b", provider: "openai-compatible", expected: ModelFamily.NATIVE_GPT_5, useNativeTools: true },
				{ id: "gpt-5", provider: "cline", expected: ModelFamily.GPT_5, useNativeTools: false },
				{ id: "gpt-5-1", provider: "openai-native", expected: ModelFamily.NATIVE_GPT_5_1, useNativeTools: true },
				{ id: "openai/gpt-5", expected: ModelFamily.NEXT_GEN },
				{ id: "gemini3", provider: "vertex", expected: ModelFamily.GEMINI_3, useNativeTools: true },
				{ id: "unknown-model", expected: ModelFamily.GENERIC },
			]

			for (const { id, expected, provider, useNativeTools } of testCases) {
				const providerId = provider ?? "random"
				const customPrompt = provider === "lmstudio" ? "compact" : undefined
				const providerInfo = { ...mockProviderInfo, providerId, model: { ...mockProviderInfo.model, id }, customPrompt }
				const result = registry.getModelFamily({
					...mockContext,
					providerInfo,
					enableNativeToolCalls: useNativeTools ?? false,
				})
				expect(result).to.equal(expected, `Failed for model ${id} with provider ${providerId}`)
			}
		})
	})

	describe("get method", () => {
		it("should handle fallback to generic variant", async () => {
			try {
				// Try to get a prompt for an unknown model
				// This should fallback to generic or throw an appropriate error
				const prompt = await registry.get(mockContext)

				// If we get a prompt, it should be a string
				expect(prompt).to.be.a("string")
				if (prompt.length > 0) {
					expect(prompt.length).to.be.greaterThan(10)
				}
			} catch (error) {
				// It's okay if it throws an error about missing variants
				expect(error).to.be.instanceOf(Error)
			}
		})
	})

	describe("native tools", () => {
		it("should not include focus_chain in native tools output", async () => {
			const nativeContext: SystemPromptContext = {
				...mockContext,
				enableNativeToolCalls: true,
				providerInfo: {
					...mockProviderInfo,
					providerId: "openai-native",
					model: { ...mockProviderInfo.model, id: "gpt-5" },
				},
			}

			await registry.get(nativeContext)
			const nativeTools = registry.nativeTools

			expect(nativeTools).to.be.an("array").that.is.not.empty

			// OpenAI-native tools are function tools; keep a fallback for other providers.
			const toolNames = (nativeTools as any[]).map((tool) => {
				if (tool?.type === "function") {
					return tool.function?.name
				}
				return tool?.name
			})

			expect(toolNames).to.not.include("focus_chain")
			expect(JSON.stringify(nativeTools)).to.not.include('"focus_chain"')
		})
	})

	describe("getAvailableModels", () => {
		it("should return list of available model IDs", () => {
			const models = registry.getAvailableModels()
			expect(models).to.be.an("array")
			// Should be empty initially since no variants are loaded
			expect(models.length).to.be.greaterThanOrEqual(0)
		})
	})

	describe("registerComponent", () => {
		it("should register custom components", () => {
			const mockComponent = async () => "CUSTOM COMPONENT"

			registry.registerComponent("custom", mockComponent)

			expect((registry as any).components.custom).to.equal(mockComponent)
		})
	})

	describe("basic functionality", () => {
		it("should be able to create registry instance", () => {
			expect(registry).to.be.instanceOf(PromptRegistry)
		})

		it("should have required methods", () => {
			expect(registry.get).to.be.a("function")
			expect(registry.getVersion).to.be.a("function")
			expect(registry.getByTag).to.be.a("function")
			expect(registry.registerComponent).to.be.a("function")
			expect(registry.getAvailableModels).to.be.a("function")
		})
	})
})

import { expect } from "chai"
import type { McpHub } from "@/services/mcp/McpHub"
import { TemplateEngine } from "../templates/TemplateEngine"
import type { SystemPromptContext } from "../types"
import { mockProviderInfo } from "./integration.test"

describe("TemplateEngine", () => {
	let templateEngine: TemplateEngine

	beforeEach(() => {
		templateEngine = new TemplateEngine()
	})

	describe("resolve", () => {
		const mockContext: SystemPromptContext = {
			cwd: "/test/project",
			ide: "TestIde",
			supportsBrowserUse: true,
			mcpHub: {
				getServers: () => [],
				getMcpServersPath: () => "/test/mcp-servers",
				getSettingsDirectoryPath: () => "/test/settings",
				clientVersion: "1.0.0",
				disposables: [],
			} as unknown as McpHub,
			focusChainSettings: {
				enabled: true,
				remindClineInterval: 6,
			},
			browserSettings: {
				viewport: {
					width: 1280,
					height: 720,
				},
			},
			isTesting: true,
			providerInfo: mockProviderInfo,
			yoloModeToggled: false,
		}

		it("should resolve simple placeholders", () => {
			const template = "Hello {{name}}!"
			const placeholders = { name: "World" }
			const result = templateEngine.resolve(template, mockContext, placeholders)
			expect(result).to.equal("Hello World!")
		})

		it("should resolve multiple placeholders", () => {
			const template = "{{greeting}} {{name}}, today is {{day}}"
			const placeholders = {
				greeting: "Hello",
				name: "Alice",
				day: "Monday",
			}
			const result = templateEngine.resolve(template, mockContext, placeholders)
			expect(result).to.equal("Hello Alice, today is Monday")
		})

		it("should handle nested object placeholders", () => {
			const template = "User: {{user.name}}, Age: {{user.age}}"
			const placeholders = {
				user: {
					name: "John",
					age: 30,
				},
			}
			const result = templateEngine.resolve(template, mockContext, placeholders)
			expect(result).to.equal("User: John, Age: 30")
		})

		it("should preserve unmatched placeholders", () => {
			const template = "Hello {{name}}, your {{missing}} is pending"
			const placeholders = { name: "Alice" }
			const result = templateEngine.resolve(template, mockContext, placeholders)
			expect(result).to.equal("Hello Alice, your {{missing}} is pending")
		})

		it("should handle object and array values", () => {
			const template = "Config: {{config}}"
			const placeholders = {
				config: { key: "value", items: [1, 2, 3] },
			}
			const result = templateEngine.resolve(template, mockContext, placeholders)
			expect(result).to.equal('Config: {"key":"value","items":[1,2,3]}')
		})

		it("should handle whitespace around placeholder names", () => {
			const template = "Hello {{ name }}, welcome to {{  place  }}"
			const placeholders = { name: "Bob", place: "Paradise" }
			const result = templateEngine.resolve(template, mockContext, placeholders)
			expect(result).to.equal("Hello Bob, welcome to Paradise")
		})
	})

	describe("extractPlaceholders", () => {
		it("should extract all unique placeholders", () => {
			const template = "Hello {{name}}, {{greeting}} {{name}}!"
			const placeholders = templateEngine.extractPlaceholders(template)
			expect(placeholders).to.deep.equal(["name", "greeting"])
		})

		it("should handle nested placeholders", () => {
			const template = "User {{user.name}} lives in {{user.location.city}}"
			const placeholders = templateEngine.extractPlaceholders(template)
			expect(placeholders).to.deep.equal(["user.name", "user.location.city"])
		})

		it("should handle whitespace in placeholders", () => {
			const template = "Hello {{  name  }} and {{greeting}}"
			const placeholders = templateEngine.extractPlaceholders(template)
			expect(placeholders).to.deep.equal(["name", "greeting"])
		})

		it("should return empty array for template without placeholders", () => {
			const template = "Hello World!"
			const placeholders = templateEngine.extractPlaceholders(template)
			expect(placeholders).to.deep.equal([])
		})
	})

	describe("validate", () => {
		it("should return missing placeholders", () => {
			const template = "Hello {{name}}, your order is ready"
			const required = ["name", "missing"]
			const missing = templateEngine.validate(template, required)
			expect(missing).to.deep.equal(["missing"])
		})

		it("should return empty array when all required placeholders are present", () => {
			const template = "Hello {{name}}, your {{item}} is ready"
			const required = ["name", "item"]
			const missing = templateEngine.validate(template, required)
			expect(missing).to.deep.equal([])
		})
	})

	describe("escape and unescape", () => {
		it("should escape placeholder markers", () => {
			const template = "Hello {{name}}!"
			const escaped = templateEngine.escape(template)
			expect(escaped).to.equal("Hello \\{\\{name\\}\\}!")
		})

		it("should unescape placeholder markers", () => {
			const escaped = "Hello \\{\\{name\\}\\}!"
			const unescaped = templateEngine.unescape(escaped)
			expect(unescaped).to.equal("Hello {{name}}!")
		})

		it("should handle round-trip escaping/unescaping", () => {
			const template = "Hello {{name}}! Welcome to {{place}}."
			const escaped = templateEngine.escape(template)
			const unescaped = templateEngine.unescape(escaped)
			expect(unescaped).to.equal(template)
		})
	})
})

