	{ family: ModelFamily.GLM, modelId: "glm-4.6", providerId: "zai" },
	{ family: ModelFamily.HERMES, modelId: "hermes-4", providerId: "test" },
	{ family: ModelFamily.DEVSTRAL, modelId: "devstral", providerId: "cline" },
	{ family: ModelFamily.NEXT_GEN, modelId: "claude-sonnet-4", providerId: "anthropic" },
	{ family: ModelFamily.XS, modelId: "qwen3_coder", providerId: "lmstudio" },
	{ family: ModelFamily.NATIVE_NEXT_GEN, modelId: "claude-4-5-sonnet", providerId: "cline" },
	{ family: ModelFamily.GPT_5, modelId: "gpt-5", providerId: "openai" },
	{ family: ModelFamily.NATIVE_GPT_5, modelId: "gpt-5-codex", providerId: "openai" },
	{ family: ModelFamily.NATIVE_GPT_5_1, modelId: "gpt-5-1", providerId: "openai" },
	{ family: ModelFamily.GEMINI_3, modelId: "gemini-3", providerId: "vertex" },
	{ family: ModelFamily.TRINITY, modelId: "arcee-ai/trinity-large-preview", providerId: "openrouter" },
]
const gemini3ModelTestCases = modelTestCases.filter(({ family }) => family === ModelFamily.GEMINI_3)

// ============================================================================
// Tests
// ============================================================================

describe("Prompt System Integration Tests", () => {
	before(async () => {
		console.log(UPDATE_SNAPSHOTS ? "🔄 SNAPSHOT UPDATE MODE" : "✅ SNAPSHOT TEST MODE")
		await fs.mkdir(SNAPSHOTS_DIR, { recursive: true }).catch(() => {})
	})

	describe("Snapshot Testing", () => {
		for (const { family, modelId, providerId } of modelTestCases) {
			describe(`${family} Model Group`, () => {
				const enableNativeToolCalls = isNativeToolsFamily(family)

				it(`should generate consistent native tools object when enabled`, async function () {
					const context: SystemPromptContext = {
						...baseContext,
						providerInfo: makeProviderInfo(modelId, providerId),
						enableNativeToolCalls,
					}

					await runPromptTest(this, context, modelId, async ({ tools }) => {
						if (!enableNativeToolCalls) {
							expect(tools).to.be.undefined
							return
						}

						expect(tools).to.be.an("array").that.is.not.empty
						const toolNames = (tools as any[]).map((tool) => {
							if (tool?.type === "function") {
								return tool.function?.name
							}
							return tool?.name
						})
						expect(toolNames).to.not.include("focus_chain")
						expect(JSON.stringify(tools)).to.not.include('"focus_chain"')
						const snapshotName = `${providerId}_${family.replace(/[^a-zA-Z0-9]/g, "_")}.tools.snap`
						await assertSnapshot(snapshotName, JSON.stringify(tools, null, 2))
					})
				})

				for (const { name: contextName, override } of contextVariations) {
					it(`should generate consistent prompt for ${providerId}/${modelId} with ${contextName} context`, async function () {
						const context: SystemPromptContext = {
							...baseContext,
							...override,
							providerInfo: makeProviderInfo(modelId, providerId),
							enableNativeToolCalls,
						}

						await runPromptTest(this, context, modelId, async ({ systemPrompt, tools }) => {
							if (enableNativeToolCalls) {
								expect(tools).to.be.an("array").that.is.not.empty
								const toolNames = (tools as any[]).map((tool) => {
									if (tool?.type === "function") {
										return tool.function?.name
									}
									return tool?.name
								})
								expect(toolNames).to.not.include("focus_chain")
							} else {
								expect(tools).to.be.undefined
							}

							expect(systemPrompt).to.be.a("string").with.length.greaterThan(100)
							expect(systemPrompt).to.not.include("{{TOOL_USE_SECTION}}")

							const snapshotName = `${providerId}_${modelId.replace(/[^a-zA-Z0-9]/g, "_")}-${contextName}.snap`
							await assertSnapshot(snapshotName, systemPrompt)
						})
					})
				}
			})
		}

		describe("Gemini 3 Specific", () => {
			for (const { family, modelId, providerId } of gemini3ModelTestCases) {
				const enableNativeToolCalls = isNativeToolsFamily(family)
				it(`should include parallel tool-calling guidance for ${providerId}/${modelId} when enabled`, async function () {
					const context: SystemPromptContext = {
						...baseContext,
						providerInfo: makeProviderInfo(modelId, providerId),
						enableNativeToolCalls,
						enableParallelToolCalling: true,
					}

					await runPromptTest(this, context, modelId, async ({ systemPrompt }) => {
						expect(systemPrompt).to.include(
							"- When multiple operations are independent (for example reading several files or searching in multiple directories), call multiple tools in a single response rather than one at a time.",
						)
						const snapshotName = `${providerId}_${modelId.replace(/[^a-zA-Z0-9]/g, "_")}-parallel-tools.snap`
						await assertSnapshot(snapshotName, systemPrompt)
					})
				})
			}
		})
	})

	describe("Context-Specific Features", () => {
		const featureTests = [
			{ name: "browser-specific content when browser is enabled", context: { supportsBrowserUse: true }, check: "browser" },
			{ name: "MCP content when MCP servers are present", context: {}, check: "MCP" },
			{ name: "TODO content when focus chain is enabled", context: {}, check: "TODO" },
			{ name: "user instructions when provided", context: {}, check: "USER'S CUSTOM INSTRUCTIONS" },
		]

		for (const { name, context, check } of featureTests) {
			it(`should include ${name}`, async function () {
				await runPromptTest(this, { ...baseContext, ...context }, "default", async ({ systemPrompt }) => {
					expect(systemPrompt.toLowerCase()).to.include(check.toLowerCase())
				})
			})
		}
	})

	describe("Error Handling", () => {
		it("should handle completely invalid context gracefully", async function () {
			this.timeout(TEST_TIMEOUT)
			const { systemPrompt } = await getSystemPrompt({} as SystemPromptContext)
			expect(systemPrompt).to.be.a("string")
		})

		it("should handle undefined context properties", async function () {
			this.timeout(TEST_TIMEOUT)
			const contextWithNulls: SystemPromptContext = {
				cwd: undefined,
				ide: "",
				supportsBrowserUse: undefined,
				mcpHub: undefined,
				focusChainSettings: undefined,
				providerInfo: mockProviderInfo,
			}

			try {
				const { systemPrompt } = await getSystemPrompt(contextWithNulls)
				expect(systemPrompt).to.be.a("string")
				expect(systemPrompt).to.include("{{TOOL_USE_SECTION}}")
			} catch (error) {
				expect(error).to.be.instanceOf(Error)
			}
		})
	})
})

/**
 * Test to verify the new matcher-based variant selection works correctly
 */

import { ApiProviderInfo } from "@/core/api"
import { McpHub } from "@/services/mcp/McpHub"
import { ModelFamily } from "@/shared/prompts"
import { SystemPromptContext } from "../types"
import { VARIANT_CONFIGS } from "../variants"

// Mock provider info objects for testing
const mockProviderInfos: { name: string; providerInfo: ApiProviderInfo; expectedFamily: ModelFamily }[] = [
	{
		name: "GPT-5 model",
		providerInfo: {
			providerId: "openai",
			model: { id: "gpt-5", info: {} as any },
			mode: "act" as const,
		},
		expectedFamily: ModelFamily.GPT_5,
	},
	{
		name: "Next-gen model",
		providerInfo: {
			providerId: "anthropic",
			model: { id: "claude-3.5-sonnet-20241022", info: {} as any },
			mode: "act" as const,
		},
		expectedFamily: ModelFamily.NEXT_GEN,
	},
	{
		name: "Compact local model",
		providerInfo: {
			providerId: "ollama",
			model: { id: "llama-3.2-1b", info: {} as any },
			mode: "act" as const,
			customPrompt: "compact",
		},
		expectedFamily: ModelFamily.XS,
	},
	{
		name: "Generic model",
		providerInfo: {
			providerId: "openai",
			model: { id: "gpt-3.5-turbo", info: {} as any },
			mode: "act" as const,
		},
		expectedFamily: ModelFamily.GENERIC,
	},
]

/**
 * Test the matcher logic for each variant
 */
export function testVariantMatching() {
	console.log("🧪 Testing variant matching logic...")

	for (const { name, providerInfo, expectedFamily } of mockProviderInfos) {
		console.log(`\n📝 Testing: ${name}`)
		console.log(`   Model: ${providerInfo.model.id}`)
		console.log(`   Provider: ${providerInfo.providerId}`)
		console.log(`   Custom Prompt: ${providerInfo.customPrompt || "none"}`)
		console.log(`   Expected Family: ${expectedFamily}`)

		let matchedFamily: ModelFamily | null = null

		// Test each variant's matcher function
		for (const [familyId, config] of Object.entries(VARIANT_CONFIGS)) {
			const mockContext = {
				cwd: "/test/project",
				ide: "TestIde",
				supportsBrowserUse: true,
				mcpHub: {
					getServers: () => [
						{
							name: "test-server",
							status: "connected",
							config: '{"command": "test"}',
							tools: [
								{
									name: "test_tool",
									description: "A test tool",
									inputSchema: { type: "object", properties: {} },
								},
							],
							resources: [],
							resourceTemplates: [],
						},
					],
				} as unknown as McpHub,
				focusChainSettings: {
					enabled: true,
					remindClineInterval: 6,
				},
				browserSettings: {
					viewport: {
						width: 1280,
						height: 720,
					},
				},
				globalClineRulesFileInstructions: "Follow global rules",
				localClineRulesFileInstructions: "Follow local rules",
				preferredLanguageInstructions: "Prefer TypeScript",
				isTesting: true,
				enableNativeToolCalls: false,
				providerInfo,
			} satisfies SystemPromptContext

			try {
				if (config.matcher(mockContext)) {
					matchedFamily = familyId as ModelFamily
					console.log(`   ✅ Matched: ${familyId}`)
					break
				}
			} catch (error) {
				console.log(`   ❌ Matcher error for ${familyId}: ${error}`)
			}
		}

		// Check if the match is correct
		if (matchedFamily === expectedFamily) {
			console.log(`   🎯 PASS: Correctly matched ${expectedFamily}`)
		} else {
			console.log(`   🚨 FAIL: Expected ${expectedFamily}, got ${matchedFamily || "null"}`)
		}
	}

	console.log("\n✨ Variant matching test completed!")
}

// Export for potential use in other tests
export { mockProviderInfos }

import { expect } from "chai"
import { before, describe, it } from "mocha"
import { ModelFamily } from "@/shared/prompts"
import { ClineDefaultTool } from "@/shared/tools"
import { ClineToolSet } from "../registry/ClineToolSet"
import { PromptRegistry } from "../registry/PromptRegistry"
import { new_task_variants } from "../tools/new_task"
import type { SystemPromptContext } from "../types"
import { mockProviderInfo } from "./integration.test"

const baseContext: SystemPromptContext = {
	cwd: "/test/project",
	ide: "TestIde",
	supportsBrowserUse: true,
	providerInfo: mockProviderInfo,
	isTesting: true,
}

describe("new_task tool contextRequirements", () => {
	before(() => {
		// Ensure tools are registered via PromptRegistry initialization
		PromptRegistry.getInstance()
	})

	const genericVariant = new_task_variants.find((v) => v.variant === ModelFamily.GENERIC)

	it("should have a contextRequirements function defined", () => {
		expect(genericVariant).to.exist
		expect(genericVariant!.contextRequirements).to.be.a("function")
	})

	it("should be enabled when yoloModeToggled is false", () => {
		const context: SystemPromptContext = { ...baseContext, yoloModeToggled: false }
		expect(genericVariant!.contextRequirements!(context)).to.be.true
	})

	it("should be enabled when yoloModeToggled is undefined", () => {
		const context: SystemPromptContext = { ...baseContext, yoloModeToggled: undefined }
		expect(genericVariant!.contextRequirements!(context)).to.be.true
	})

	it("should be disabled when yoloModeToggled is true", () => {
		const context: SystemPromptContext = { ...baseContext, yoloModeToggled: true }
		expect(genericVariant!.contextRequirements!(context)).to.be.false
	})

	it("should follow the same pattern as ask_followup_question", () => {
		const newTaskTool = ClineToolSet.getToolByNameWithFallback(ClineDefaultTool.NEW_TASK, ModelFamily.GENERIC)
		const askTool = ClineToolSet.getToolByNameWithFallback(ClineDefaultTool.ASK, ModelFamily.GENERIC)

		expect(newTaskTool).to.exist
		expect(askTool).to.exist
		expect(newTaskTool!.config.contextRequirements).to.be.a("function")
		expect(askTool!.config.contextRequirements).to.be.a("function")

		const yoloContext: SystemPromptContext = { ...baseContext, yoloModeToggled: true }
		const normalContext: SystemPromptContext = { ...baseContext, yoloModeToggled: false }

		expect(newTaskTool!.config.contextRequirements!(yoloContext)).to.be.false
		expect(askTool!.config.contextRequirements!(yoloContext)).to.be.false

		expect(newTaskTool!.config.contextRequirements!(normalContext)).to.be.true
		expect(askTool!.config.contextRequirements!(normalContext)).to.be.true
	})
})

import { expect } from "chai"
import { beforeEach, describe, it } from "mocha"
import type { ApiProviderInfo } from "@/core/api"
import { ModelFamily } from "@/shared/prompts"
import { ClineDefaultTool } from "@/shared/tools"
import { getSystemPrompt } from "../index"
import { PromptRegistry } from "../registry/PromptRegistry"
import type { SystemPromptContext } from "../types"

const makeContext = (modelId: string): SystemPromptContext => ({
	cwd: "/test/project",
	ide: "TestIde",
	supportsBrowserUse: true,
	clineWebToolsEnabled: true,
	focusChainSettings: { enabled: true, remindClineInterval: 6 },
	browserSettings: { viewport: { width: 1280, height: 720 } },
	isTesting: true,
	enableNativeToolCalls: true,
	providerInfo: {
		providerId: "openai-compatible",
		model: { id: modelId, info: { supportsPromptCache: false } as any },
		mode: "act",
	} satisfies ApiProviderInfo,
})

const toolNamesFrom = (tools: Awaited<ReturnType<typeof getSystemPrompt>>["tools"]): string[] =>
	(tools ?? [])
		.map((tool: any) => tool?.function?.name ?? tool?.name)
		.filter((name): name is string => typeof name === "string")

describe("OpenAI-compatible gpt-oss native tools smoke test", () => {
	beforeEach(() => {
		PromptRegistry.dispose()
	})

	it("uses the NATIVE_GPT_5 prompt family for gpt-oss when native tools are enabled", async () => {
		const registry = PromptRegistry.getInstance()
		await registry.load()
		const family = registry.getModelFamily(makeContext("gpt-oss-120b"))

		expect(family).to.equal(ModelFamily.NATIVE_GPT_5)
	})

	it("exposes apply_patch for gpt-oss-120b so file editing remains native", async () => {
		const { tools } = await getSystemPrompt(makeContext("gpt-oss-120b"))
		const toolNames = toolNamesFrom(tools)

		expect(toolNames).to.include(ClineDefaultTool.BASH)
		expect(toolNames).to.include(ClineDefaultTool.FILE_READ)
		expect(toolNames).to.include(ClineDefaultTool.APPLY_PATCH)
		expect(toolNames).to.not.include(ClineDefaultTool.FILE_NEW)
		expect(toolNames).to.not.include(ClineDefaultTool.FILE_EDIT)
	})

	it("control: gpt-5-codex still receives apply_patch", async () => {
		const { tools } = await getSystemPrompt(makeContext("gpt-5-codex"))
		const toolNames = toolNamesFrom(tools)

		expect(toolNames).to.include(ClineDefaultTool.APPLY_PATCH)
	})
})

import { expect } from "chai"
import { describe, it } from "mocha"
import { ModelFamily } from "@/shared/prompts"
import { ClineDefaultTool } from "@/shared/tools"
import type { ClineToolSpec } from "../spec"
import { toolSpecFunctionDeclarations, toolSpecFunctionDefinition, toolSpecInputSchema } from "../spec"
import type { SystemPromptContext } from "../types"

const mockContext: SystemPromptContext = {
	cwd: "/test/project",
	ide: "TestIde",
	supportsBrowserUse: true,
	clineWebToolsEnabled: true,
	subagentsEnabled: true,
	providerInfo: { providerId: "test", model: { id: "test-model", info: { supportsPromptCache: false } }, mode: "act" },
	enableNativeToolCalls: false,
	isTesting: true,
}

const makeTool = (overrides?: Partial<ClineToolSpec>): ClineToolSpec => ({
	variant: ModelFamily.GENERIC,
	id: ClineDefaultTool.FILE_READ,
	name: "read_file",
	description: "Read a file",
	parameters: [
		{
			name: "path",
			required: true,
			instruction: "The path of the file to read relative to {{CWD}}",
		},
		{
			name: "optional_param",
			required: false,
			instruction: "An optional parameter",
		},
	],
	...overrides,
})

describe("toolSpecFunctionDeclarations (Gemini)", () => {
	it("includes parameter descriptions from instruction field", () => {
		const result = toolSpecFunctionDeclarations(makeTool(), mockContext)

		const pathParam = result.parameters?.properties?.["path"] as any
		expect(pathParam).to.exist
		expect(pathParam.description).to.be.a("string")
		expect(pathParam.description).to.include("path of the file to read")
	})

	it("includes descriptions for all parameters", () => {
		const result = toolSpecFunctionDeclarations(makeTool(), mockContext)

		const props = result.parameters?.properties as any
		expect(props["path"].description).to.be.a("string").and.not.be.empty
		expect(props["optional_param"].description).to.be.a("string").and.not.be.empty
	})

	it("handles function-type instructions", () => {
		const tool = makeTool({
			parameters: [
				{
					name: "dynamic",
					required: true,
					instruction: (ctx: SystemPromptContext) => `Dynamic value: ${ctx.cwd}`,
				},
			],
		})
		const result = toolSpecFunctionDeclarations(tool, mockContext)

		const param = result.parameters?.properties?.["dynamic"] as any
		expect(param.description).to.equal("Dynamic value: /test/project")
	})

	it("omits description when instruction is empty", () => {
		const tool = makeTool({
			parameters: [{ name: "empty", required: false, instruction: "" }],
		})
		const result = toolSpecFunctionDeclarations(tool, mockContext)

		const param = result.parameters?.properties?.["empty"] as any
		expect(param.description).to.be.undefined
	})
})

describe("Gemini and Anthropic parameter descriptions match", () => {
	it("both converters produce the same description text", () => {
		const tool = makeTool()
		const gemini = toolSpecFunctionDeclarations(tool, mockContext)
		const anthropic = toolSpecInputSchema(tool, mockContext)

		const geminiDesc = (gemini.parameters?.properties?.["path"] as any)?.description
		const anthropicDesc = (anthropic.input_schema as any).properties["path"]?.description

		expect(geminiDesc).to.equal(anthropicDesc)
	})
})

describe("native tool placeholder replacement", () => {
	it("replaces CWD and MULTI_ROOT_HINT placeholders in descriptions", () => {
		const context: SystemPromptContext = {
			...mockContext,
			isMultiRootEnabled: true,
		}
		const tool = makeTool({
			parameters: [
				{
					name: "path",
					required: true,
					instruction: "Path (relative to {{CWD}}){{MULTI_ROOT_HINT}}",
				},
			],
		})

		const openAI = toolSpecFunctionDefinition(tool, context)
		const anthropic = toolSpecInputSchema(tool, context)
		const gemini = toolSpecFunctionDeclarations(tool, context)

		const openAIDesc = ((openAI as any).function.parameters.properties.path as any).description as string
		const anthropicDesc = ((anthropic as any).input_schema.properties.path as any).description as string
		const geminiDesc = (gemini.parameters?.properties?.["path"] as any)?.description as string

		for (const desc of [openAIDesc, anthropicDesc, geminiDesc]) {
			expect(desc).to.include("/test/project")
			expect(desc).to.include("Use @workspace:path syntax")
			expect(desc).to.not.include("{{CWD}}")
			expect(desc).to.not.include("{{MULTI_ROOT_HINT}}")
		}
	})
})
